export interface ConnectorConfig {
  /** Airtable Personal Access Token (from env var AIRTABLE_PAT) */
  airtablePat: string;
  /** Airtable Base ID (e.g., appXXXXXXXXXXXX) */
  baseId: string;
  /** Airtable Table Name or ID */
  tableName: string;
  /** Optional: Airtable Record ID. If omitted, the connector will search for a record by email. */
  recordId?: string;
  /** Injected fetch for testing (defaults to global fetch) */
  fetch?: typeof fetch;
}

export interface JotformSubmission {
  email: string;
  first_name?: string;
  last_name?: string;
  phone?: string;
  address?: string;
  [key: string]: unknown;
}

export interface HandleResult {
  recordId: string;
  updatedFields: string[];
}

async function findRecordByEmail(
  config: ConnectorConfig,
  email: string,
): Promise<string> {
  const fetchFn = config.fetch ?? fetch;
  const formula = encodeURIComponent(`{Email} = '${email.replace(/'/g, "\\'")}'`);
  const url = `https://api.airtable.com/v0/${config.baseId}/${config.tableName}?filterByFormula=${formula}`;
  const response = await fetchFn(url, {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${config.airtablePat}`,
      'Content-Type': 'application/json',
    },
  });

  if (!response.ok) {
    throw new Error(`Airtable search failed: ${response.status} ${response.statusText} at GET ${url}`);
  }

  const data = (await response.json()) as { records?: Array<{ id: string }> };
  if (!data.records || data.records.length === 0) {
    throw new Error(`No Airtable record found for email: ${email}`);
  }
  if (data.records.length > 1) {
    throw new Error(`Multiple Airtable records found for email: ${email}`);
  }
  return data.records[0].id;
}

function buildFields(payload: JotformSubmission): Record<string, string> {
  const fields: Record<string, string> = {};
  if (payload.first_name?.trim()) fields['First Name'] = payload.first_name.trim();
  if (payload.last_name?.trim()) fields['Last Name'] = payload.last_name.trim();
  if (payload.phone?.trim()) fields['Phone'] = payload.phone.trim();
  if (payload.address?.trim()) fields['Address'] = payload.address.trim();
  return fields;
}

export async function handle(payload: JotformSubmission, config: ConnectorConfig): Promise<HandleResult> {
  if (!payload.email?.trim()) {
    throw new Error('Missing required field: email');
  }

  const fetchFn = config.fetch ?? fetch;
  const email = payload.email.trim();

  const recordId = config.recordId ?? (await findRecordByEmail(config, email));

  const fields = buildFields(payload);
  if (Object.keys(fields).length === 0) {
    return { recordId, updatedFields: [] };
  }

  const url = `https://api.airtable.com/v0/${config.baseId}/${config.tableName}/${recordId}`;
  const response = await fetchFn(url, {
    method: 'PATCH',
    headers: {
      Authorization: `Bearer ${config.airtablePat}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ fields }),
  });

  if (!response.ok) {
    throw new Error(`Airtable update failed: ${response.status} ${response.statusText} at PATCH ${url}`);
  }

  const data = (await response.json()) as { id: string; fields: Record<string, unknown> };
  return {
    recordId: data.id,
    updatedFields: Object.keys(fields),
  };
}

import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, JotformSubmission } from './connector';
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, TARGET_ENDPOINTS } from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      airtablePat: 'pat-test-token',
      baseId: 'appXXXXXXXXXXXX',
      tableName: 'Table%201',
      recordId: 'recXXXXXXXXXXXX',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as JotformSubmission, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.recordId).toBe('recXXXXXXXXXXXX');
    expect(result.updatedFields).toEqual(['First Name', 'Last Name', 'Phone', 'Address']);
  });
});

describe('handle', () => {
  it('throws when email is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 500));
    const config: ConnectorConfig = {
      airtablePat: 'pat-test',
      baseId: 'appTest',
      tableName: 'Table',
      fetch,
    };
    const payload = { first_name: 'John' } as JotformSubmission;
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: email');
  });

  it('throws when email is empty string', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 500));
    const config: ConnectorConfig = {
      airtablePat: 'pat-test',
      baseId: 'appTest',
      tableName: 'Table',
      fetch,
    };
    const payload = { email: '   ', first_name: 'John' } as JotformSubmission;
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: email');
  });

  it('uses provided recordId and patches non-empty fields', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.method).toBe('PATCH');
      expect(req.url).toBe('https://api.airtable.com/v0/appTest/Table%201/rec123');
      expect(req.json).toEqual({
        fields: {
          'First Name': 'John',
          'Last Name': 'Doe',
        },
      });
      return jsonResponse({ id: 'rec123', fields: { 'First Name': 'John', 'Last Name': 'Doe' } }, 200);
    });
    const config: ConnectorConfig = {
      airtablePat: 'pat-test',
      baseId: 'appTest',
      tableName: 'Table 1',
      recordId: 'rec123',
      fetch,
    };
    const payload: JotformSubmission = {
      email: 'user@example.com',
      first_name: 'John',
      last_name: 'Doe',
      phone: '',
      address: '   ',
    };
    const result = await handle(payload, config);
    expect(calls.length).toBe(1);
    expect(result.recordId).toBe('rec123');
    expect(result.updatedFields).toEqual(['First Name', 'Last Name']);
  });

  it('skips empty fields and only patches provided values', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.json).toEqual({ fields: { Phone: '555-1234' } });
      return jsonResponse({ id: 'rec456', fields: { Phone: '555-1234' } }, 200);
    });
    const config: ConnectorConfig = {
      airtablePat: 'pat-test',
      baseId: 'appTest',
      tableName: 'Table 1',
      recordId: 'rec456',
      fetch,
    };
    const payload: JotformSubmission = {
      email: 'user@example.com',
      first_name: '',
      last_name: '   ',
      phone: '555-1234',
      address: undefined,
    };
    const result = await handle(payload, config);
    expect(result.updatedFields).toEqual(['Phone']);
  });

  it('returns empty updatedFields when all mapped fields are empty', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      throw new Error('Should not call PATCH when no fields to update');
    });
    const config: ConnectorConfig = {
      airtablePat: 'pat-test',
      baseId: 'appTest',
      tableName: 'Table 1',
      recordId: 'rec789',
      fetch,
    };
    const payload: JotformSubmission = {
      email: 'user@example.com',
      first_name: '',
      last_name: '',
      phone: '',
      address: '',
    };
    const result = await handle(payload, config);
    expect(calls.length).toBe(0);
    expect(result.updatedFields).toEqual([]);
  });

  it('searches for record by email when recordId not provided', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url.includes('filterByFormula')) {
        expect(req.url).toContain('filterByFormula=%7BEmail%7D%20%3D%20%27user%40example.com%27');
        return jsonResponse({ records: [{ id: 'recFound' }] }, 200);
      }
      if (req.method === 'PATCH') {
        expect(req.url).toBe('https://api.airtable.com/v0/appTest/Table%201/recFound');
        return jsonResponse({ id: 'recFound', fields: { 'First Name': 'Jane' } }, 200);
      }
      return jsonResponse({ error: 'unexpected' }, 404);
    });
    const config: ConnectorConfig = {
      airtablePat: 'pat-test',
      baseId: 'appTest',
      tableName: 'Table 1',
      fetch,
    };
    const payload: JotformSubmission = {
      email: 'user@example.com',
      first_name: 'Jane',
    };
    const result = await handle(payload, config);
    expect(calls.length).toBe(2);
    expect(result.recordId).toBe('recFound');
    expect(result.updatedFields).toEqual(['First Name']);
  });

  it('throws when search returns no records', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.method === 'GET') return jsonResponse({ records: [] }, 200);
      return jsonResponse({}, 500);
    });
    const config: ConnectorConfig = {
      airtablePat: 'pat-test',
      baseId: 'appTest',
      tableName: 'Table 1',
      fetch,
    };
    const payload: JotformSubmission = { email: 'missing@example.com' };
    await expect(handle(payload, config)).rejects.toThrow('No Airtable record found for email: missing@example.com');
  });

  it('throws when search returns multiple records', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.method === 'GET') return jsonResponse({ records: [{ id: 'rec1' }, { id: 'rec2' }] }, 200);
      return jsonResponse({}, 500);
    });
    const config: ConnectorConfig = {
      airtablePat: 'pat-test',
      baseId: 'appTest',
      tableName: 'Table 1',
      fetch,
    };
    const payload: JotformSubmission = { email: 'dup@example.com' };
    await expect(handle(payload, config)).rejects.toThrow('Multiple Airtable records found for email: dup@example.com');
  });

  it('throws on non-2xx response from Airtable search', async () => {
    const { fetch } = fakeFetch((req) => jsonResponse({ error: 'Unauthorized' }, 401));
    const config: ConnectorConfig = {
      airtablePat: 'bad-pat',
      baseId: 'appTest',
      tableName: 'Table 1',
      fetch,
    };
    const payload: JotformSubmission = { email: 'user@example.com' };
    await expect(handle(payload, config)).rejects.toThrow('Airtable search failed: 401 Unauthorized at GET');
  });

  it('throws on non-2xx response from Airtable patch', async () => {
    const { fetch } = fakeFetch((req) => jsonResponse({ error: 'Not Found' }, 404));
    const config: ConnectorConfig = {
      airtablePat: 'pat-test',
      baseId: 'appTest',
      tableName: 'Table 1',
      recordId: 'recMissing',
      fetch,
    };
    const payload: JotformSubmission = { email: 'user@example.com', first_name: 'Test' };
    await expect(handle(payload, config)).rejects.toThrow('Airtable update failed: 404 Not Found at PATCH');
  });

  it('includes Authorization header with Bearer token', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.headers.get('authorization')).toBe('Bearer pat-secret');
      return jsonResponse({ id: 'rec123', fields: {} }, 200);
    });
    const config: ConnectorConfig = {
      airtablePat: 'pat-secret',
      baseId: 'appTest',
      tableName: 'Table 1',
      recordId: 'rec123',
      fetch,
    };
    const payload: JotformSubmission = { email: 'user@example.com', first_name: 'Test' };
    await handle(payload, config);
    expect(calls[0].headers.get('authorization')).toBe('Bearer pat-secret');
  });

  it('trims whitespace from field values', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.json).toEqual({ fields: { 'First Name': 'John', 'Last Name': 'Doe' } });
      return jsonResponse({ id: 'rec123', fields: { 'First Name': 'John', 'Last Name': 'Doe' } }, 200);
    });
    const config: ConnectorConfig = {
      airtablePat: 'pat-test',
      baseId: 'appTest',
      tableName: 'Table 1',
      recordId: 'rec123',
      fetch,
    };
    const payload: JotformSubmission = {
      email: 'user@example.com',
      first_name: '  John  ',
      last_name: '\tDoe\n',
    };
    await handle(payload, config);
    expect(calls[0].json).toEqual({ fields: { 'First Name': 'John', 'Last Name': 'Doe' } });
  });
});

// Written by patchbay from the API documentation. Regenerated on every attempt, do not edit.
// Source: https://www.jotform.com/answers/35936941-sometimes-the-form-doesnt-send-information-to-the-webhook
// Source: https://community.airtable.com/development-apis-11/upserting-multiple-fields-based-on-api-data-with-an-automation-script-3804

/** Example payload of the source event, as documented. */
export const SOURCE_EXAMPLE = {
  "email": "user@example.com",
  "first_name": "John",
  "last_name": "Doe",
  "phone": "555-1234",
  "address": "123 Main St"
}

export interface DocumentedEndpoint {
  method: string
  /** As documented; may contain placeholders such as {id}, :id, <id> or a region host like usX. */
  url: string
  response: unknown
}

/** Target endpoints the connector may call, in the documented order, with their documented responses. */
export const TARGET_ENDPOINTS: DocumentedEndpoint[] = [
  {
    "method": "PATCH",
    "url": "https://api.airtable.com/v0/{baseId}/{tableName}/{recordId}",
    "response": {
      "id": "recXXXXXXXXXXXX",
      "fields": {
        "First Name": "John",
        "Last Name": "Doe",
        "Phone": "555-1234",
        "Address": "123 Main St"
      },
      "createdTime": "2023-01-01T12:00:00.000Z"
    }
  }
]

export interface RecordedCall {
  method: string
  url: string
  /** The request body exactly as sent (usually a JSON string). */
  body: string | undefined
  /** The body parsed as JSON, or undefined when it is not JSON. */
  json: unknown
  headers: Headers
}

/** The documented endpoint a request matches, placeholders and region subdomains included. */
export function findEndpoint(method: string, url: string): DocumentedEndpoint | undefined {
  return TARGET_ENDPOINTS.find((endpoint) => endpoint.method === method.toUpperCase() && urlMatches(endpoint.url, url))
}

/**
 * A fake fetch that answers every documented endpoint with its documented response and
 * rejects anything else. Use it in the contract test:
 *
 *   const { fetch, calls } = contractFetch()
 *   await handle(SOURCE_EXAMPLE as MyInput, { ...config, fetch })
 *   expect(calls.length).toBeGreaterThan(0)
 */
export function contractFetch(): { fetch: typeof fetch; calls: RecordedCall[] } {
  return fakeFetch((request) => {
    const endpoint = findEndpoint(request.method, request.url)
    if (!endpoint) throw new Error(`contract: ${request.method} ${request.url} is not a documented endpoint`)
    return jsonResponse(endpoint.response)
  })
}

/**
 * A correctly typed fake fetch for every other test. The handler receives the recorded
 * request: { method, url, body (string as sent), json (parsed body), headers (Headers) }.
 *
 *   const { fetch, calls } = fakeFetch((req) => req.url.endsWith('/deals') ? jsonResponse({ id: 1 }, 201) : jsonResponse({}, 404))
 */
export function fakeFetch(
  handler: (request: RecordedCall) => Response | Promise<Response>,
): { fetch: typeof fetch; calls: RecordedCall[] } {
  const calls: RecordedCall[] = []
  const fake = async (input: string | URL | Request, init: RequestInit = {}): Promise<Response> => {
    const url = input instanceof Request ? input.url : String(input)
    const method = (init.method ?? (input instanceof Request ? input.method : 'GET')).toUpperCase()
    const body = typeof init.body === 'string' ? init.body : init.body == null ? undefined : String(init.body)
    const call: RecordedCall = { method, url, body, json: parseJson(body), headers: new Headers(init.headers) }
    calls.push(call)
    return handler(call)
  }
  return { fetch: fake as typeof fetch, calls }
}

const STATUS_TEXT: Record<number, string> = {
  200: 'OK', 201: 'Created', 202: 'Accepted', 204: 'No Content',
  400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden', 404: 'Not Found', 409: 'Conflict',
  422: 'Unprocessable Entity', 429: 'Too Many Requests',
  500: 'Internal Server Error', 502: 'Bad Gateway', 503: 'Service Unavailable',
}

/** A JSON Response with the standard status text, e.g. jsonResponse({ error: 'nope' }, 401) -> "401 Unauthorized". */
export function jsonResponse(body: unknown, status = 200): Response {
  const init = { status, statusText: STATUS_TEXT[status] ?? '', headers: { 'Content-Type': 'application/json' } }
  return new Response(status === 204 ? null : JSON.stringify(body), init)
}

function parseJson(raw: string | undefined): unknown {
  if (raw === undefined) return undefined
  try {
    return JSON.parse(raw)
  } catch {
    return undefined
  }
}

function urlMatches(template: string, actual: string): boolean {
  const t = splitUrl(template)
  const a = splitUrl(actual)
  if (!t || !a) return false
  const tHost = t.host.split('.')
  const aHost = a.host.split('.')
  if (tHost.slice(-2).join('.') !== aHost.slice(-2).join('.')) return false
  const tPath = t.path.replace(/\/+$/, '').split('/')
  const aPath = a.path.replace(/\/+$/, '').split('/')
  if (tPath.length !== aPath.length) return false
  return tPath.every((segment, i) => isPlaceholder(segment) || segment === aPath[i])
}

function splitUrl(url: string): { host: string; path: string } | null {
  const match = url.match(/^https?:\/\/([^/?#]+)([^?#]*)/i)
  return match ? { host: (match[1] ?? '').toLowerCase(), path: match[2] || '/' } : null
}

function isPlaceholder(segment: string): boolean {
  return /^\{[^}]+\}$|^:[A-Za-z_]\w*$|^<[^>]+>$/.test(segment)
}

export interface ConnectorConfig {
  /** Airtable Personal Access Token (from env var AIRTABLE_PAT) */
  airtablePat: string;
  /** Airtable Base ID (e.g., appXXXXXXXXXXXX) */
